-- complaints from lossless bronze, typed against platform/contracts/sources/complaints.yml
-- (contract 18a4337eb07c). Generated by scripts/generate_silver_from_contracts.py: do not edit, change the contract and regenerate.
-- '' and absent fields become NULL; a value that does not cast becomes NULL and is listed in _dq_issues
-- as '<column>:<code>' (see audit.dq_cell_findings). Every bronze record is kept, flagged or not.
select
    nullif(r."complaint_id", '') AS "complaint_id",
    try_cast(nullif(r."creation_date", '') AS TIMESTAMP) AS "creation_date",
    try_cast(nullif(r."process_date", '') AS DATE) AS "process_date",
    nullif(r."customer_id", '') AS "customer_id",
    nullif(r."case_type", '') AS "case_type",
    nullif(r."category", '') AS "category",
    nullif(r."subcategory", '') AS "subcategory",
    nullif(r."reception_channel", '') AS "reception_channel",
    nullif(r."affected_product_id", '') AS "affected_product_id",
    nullif(r."related_branch_id", '') AS "related_branch_id",
    nullif(r."origin_interaction_id", '') AS "origin_interaction_id",
    nullif(r."description", '') AS "description",
    try_cast(nullif(r."claimed_amount", '') AS DOUBLE) AS "claimed_amount",
    nullif(r."currency", '') AS "currency",
    nullif(r."priority", '') AS "priority",
    nullif(r."status", '') AS "status",
    nullif(r."assigned_agent_id", '') AS "assigned_agent_id",
    try_cast(nullif(r."assignment_date", '') AS TIMESTAMP) AS "assignment_date",
    try_cast(nullif(r."first_response_date", '') AS TIMESTAMP) AS "first_response_date",
    try_cast(nullif(r."resolution_date", '') AS TIMESTAMP) AS "resolution_date",
    try_cast(nullif(r."closing_date", '') AS TIMESTAMP) AS "closing_date",
    try_cast(nullif(r."sla_breached", '') AS BOOLEAN) AS "sla_breached",
    try_cast(nullif(r."resolution_days", '') AS DOUBLE) AS "resolution_days",
    nullif(r."resolution", '') AS "resolution",
    try_cast(nullif(r."compensation_granted", '') AS DOUBLE) AS "compensation_granted",
    try_cast(nullif(r."resolution_satisfaction", '') AS DOUBLE) AS "resolution_satisfaction",
    try_cast(nullif(r."is_repeat_complainer", '') AS BOOLEAN) AS "is_repeat_complainer",
    cast(r._partition_date AS date) AS _partition_date,
    r._source_file,
    r._record_no,
    r._record_sha256,
    r._parse_status,
    '18a4337eb07c' AS _contract_version,
    list_filter([
        CASE WHEN r._parse_status <> 'ok' THEN '*:G' END,
        CASE WHEN coalesce(r."complaint_id", '') = '' THEN 'complaint_id:N' END,
        CASE WHEN r."complaint_id" <> '' AND NOT regexp_full_match(r."complaint_id", 'CMP-[0-9A-Z]{20}') THEN 'complaint_id:K' END,
        CASE WHEN coalesce(r."creation_date", '') = '' THEN 'creation_date:N' END,
        CASE WHEN r."creation_date" <> '' AND try_cast(r."creation_date" AS TIMESTAMP) IS NULL THEN 'creation_date:T' END,
        CASE WHEN r."creation_date" <> '' AND NOT regexp_full_match(r."creation_date", '(?:[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}(:[0-9]{2}(\.[0-9]+)?)?)') AND try_cast(r."creation_date" AS TIMESTAMP) IS NOT NULL THEN 'creation_date:F' END,
        CASE WHEN coalesce(r."process_date", '') = '' THEN 'process_date:N' END,
        CASE WHEN r."process_date" <> '' AND try_cast(r."process_date" AS DATE) IS NULL THEN 'process_date:T' END,
        CASE WHEN r."process_date" <> '' AND NOT regexp_full_match(r."process_date", '(?:[0-9]{4}-[0-9]{2}-[0-9]{2})') AND try_cast(r."process_date" AS DATE) IS NOT NULL THEN 'process_date:F' END,
        CASE WHEN coalesce(r."customer_id", '') = '' THEN 'customer_id:N' END,
        CASE WHEN r."customer_id" <> '' AND NOT regexp_full_match(r."customer_id", 'CLI-[0-9A-Z]{12}') THEN 'customer_id:K' END,
        CASE WHEN coalesce(r."case_type", '') = '' THEN 'case_type:N' END,
        CASE WHEN r."case_type" <> '' AND r."case_type" NOT IN ('Claim', 'Complaint', 'Request', 'Suggestion') THEN 'case_type:V1' END,
        CASE WHEN coalesce(r."category", '') = '' THEN 'category:N' END,
        CASE WHEN r."category" <> '' AND r."category" NOT IN ('Branch', 'Fees', 'Service', 'Technical', 'Transactions') THEN 'category:V1' END,
        CASE WHEN r."subcategory" <> '' AND r."subcategory" NOT IN ('Atención en sucursal', 'Calidad de servicio', 'Cargo no reconocido', 'Cobro indebido', 'Problema con app') THEN 'subcategory:V1' END,
        CASE WHEN coalesce(r."reception_channel", '') = '' THEN 'reception_channel:N' END,
        CASE WHEN r."reception_channel" <> '' AND r."reception_channel" NOT IN ('App', 'Branch', 'Call Center', 'Email', 'Regulator', 'Web') THEN 'reception_channel:V1' END,
        CASE WHEN r."affected_product_id" <> '' AND NOT regexp_full_match(r."affected_product_id", 'PRD-[0-9A-Z]{12}') THEN 'affected_product_id:K' END,
        CASE WHEN r."related_branch_id" <> '' AND NOT regexp_full_match(r."related_branch_id", 'SUC-[0-9A-Z]{8}') THEN 'related_branch_id:K' END,
        CASE WHEN coalesce(r."description", '') = '' THEN 'description:N' END,
        CASE WHEN regexp_matches(r."description", '(^|[^A-Za-z])(nan|NaN|None|null|NULL|undefined)([^A-Za-z]|$)') THEN 'description:P' END,
        CASE WHEN regexp_matches(r."description", '\{[a-z_]+\}') THEN 'description:S' END,
        CASE WHEN r."claimed_amount" <> '' AND try_cast(r."claimed_amount" AS DOUBLE) IS NULL THEN 'claimed_amount:T' END,
        CASE WHEN r."claimed_amount" <> '' AND NOT regexp_full_match(r."claimed_amount", '(?:[+-]?[0-9]+)|(?:[+-]?[0-9]*\.[0-9]+)|(?:[+-]?[0-9]*\.?[0-9]+[eE][+-]?[0-9]+)') AND try_cast(r."claimed_amount" AS DOUBLE) IS NOT NULL THEN 'claimed_amount:F' END,
        CASE WHEN r."currency" <> '' AND r."currency" NOT IN ('ARS', 'COP', 'MXN', 'USD') THEN 'currency:V1' END,
        CASE WHEN coalesce(r."priority", '') = '' THEN 'priority:N' END,
        CASE WHEN r."priority" <> '' AND r."priority" NOT IN ('Critical', 'High', 'Low', 'Medium') THEN 'priority:V1' END,
        CASE WHEN coalesce(r."status", '') = '' THEN 'status:N' END,
        CASE WHEN r."status" <> '' AND r."status" NOT IN ('Closed', 'Escalated', 'In Process', 'Open', 'Rejected', 'Resolved') THEN 'status:V1' END,
        CASE WHEN r."assigned_agent_id" <> '' AND NOT regexp_full_match(r."assigned_agent_id", 'AGT-[0-9A-Z]{10}') THEN 'assigned_agent_id:K' END,
        CASE WHEN r."assignment_date" <> '' AND try_cast(r."assignment_date" AS TIMESTAMP) IS NULL THEN 'assignment_date:T' END,
        CASE WHEN r."assignment_date" <> '' AND NOT regexp_full_match(r."assignment_date", '(?:[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}(:[0-9]{2}(\.[0-9]+)?)?)') AND try_cast(r."assignment_date" AS TIMESTAMP) IS NOT NULL THEN 'assignment_date:F' END,
        CASE WHEN r."first_response_date" <> '' AND try_cast(r."first_response_date" AS TIMESTAMP) IS NULL THEN 'first_response_date:T' END,
        CASE WHEN r."first_response_date" <> '' AND NOT regexp_full_match(r."first_response_date", '(?:[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}(:[0-9]{2}(\.[0-9]+)?)?)') AND try_cast(r."first_response_date" AS TIMESTAMP) IS NOT NULL THEN 'first_response_date:F' END,
        CASE WHEN r."resolution_date" <> '' AND try_cast(r."resolution_date" AS TIMESTAMP) IS NULL THEN 'resolution_date:T' END,
        CASE WHEN r."resolution_date" <> '' AND NOT regexp_full_match(r."resolution_date", '(?:[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}(:[0-9]{2}(\.[0-9]+)?)?)') AND try_cast(r."resolution_date" AS TIMESTAMP) IS NOT NULL THEN 'resolution_date:F' END,
        CASE WHEN r."closing_date" <> '' AND try_cast(r."closing_date" AS TIMESTAMP) IS NULL THEN 'closing_date:T' END,
        CASE WHEN r."closing_date" <> '' AND NOT regexp_full_match(r."closing_date", '(?:[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}(:[0-9]{2}(\.[0-9]+)?)?)') AND try_cast(r."closing_date" AS TIMESTAMP) IS NOT NULL THEN 'closing_date:F' END,
        CASE WHEN coalesce(r."sla_breached", '') = '' THEN 'sla_breached:N' END,
        CASE WHEN r."sla_breached" <> '' AND try_cast(r."sla_breached" AS BOOLEAN) IS NULL THEN 'sla_breached:T' END,
        CASE WHEN r."sla_breached" <> '' AND NOT regexp_full_match(r."sla_breached", '(?i:(true|false))') AND try_cast(r."sla_breached" AS BOOLEAN) IS NOT NULL THEN 'sla_breached:F' END,
        CASE WHEN r."resolution_days" <> '' AND try_cast(r."resolution_days" AS DOUBLE) IS NULL THEN 'resolution_days:T' END,
        CASE WHEN r."resolution_days" <> '' AND NOT regexp_full_match(r."resolution_days", '(?:[+-]?[0-9]+)|(?:[+-]?[0-9]*\.[0-9]+)|(?:[+-]?[0-9]*\.?[0-9]+[eE][+-]?[0-9]+)') AND try_cast(r."resolution_days" AS DOUBLE) IS NOT NULL THEN 'resolution_days:F' END,
        CASE WHEN regexp_matches(r."resolution", '(^|[^A-Za-z])(nan|NaN|None|null|NULL|undefined)([^A-Za-z]|$)') THEN 'resolution:P' END,
        CASE WHEN regexp_matches(r."resolution", '\{[a-z_]+\}') THEN 'resolution:S' END,
        CASE WHEN r."compensation_granted" <> '' AND try_cast(r."compensation_granted" AS DOUBLE) IS NULL THEN 'compensation_granted:T' END,
        CASE WHEN r."compensation_granted" <> '' AND NOT regexp_full_match(r."compensation_granted", '(?:[+-]?[0-9]+)|(?:[+-]?[0-9]*\.[0-9]+)|(?:[+-]?[0-9]*\.?[0-9]+[eE][+-]?[0-9]+)') AND try_cast(r."compensation_granted" AS DOUBLE) IS NOT NULL THEN 'compensation_granted:F' END,
        CASE WHEN r."resolution_satisfaction" <> '' AND try_cast(r."resolution_satisfaction" AS DOUBLE) IS NULL THEN 'resolution_satisfaction:T' END,
        CASE WHEN r."resolution_satisfaction" <> '' AND NOT regexp_full_match(r."resolution_satisfaction", '(?:[+-]?[0-9]+)|(?:[+-]?[0-9]*\.[0-9]+)|(?:[+-]?[0-9]*\.?[0-9]+[eE][+-]?[0-9]+)') AND try_cast(r."resolution_satisfaction" AS DOUBLE) IS NOT NULL THEN 'resolution_satisfaction:F' END,
        CASE WHEN coalesce(r."is_repeat_complainer", '') = '' THEN 'is_repeat_complainer:N' END,
        CASE WHEN r."is_repeat_complainer" <> '' AND try_cast(r."is_repeat_complainer" AS BOOLEAN) IS NULL THEN 'is_repeat_complainer:T' END,
        CASE WHEN r."is_repeat_complainer" <> '' AND NOT regexp_full_match(r."is_repeat_complainer", '(?i:(true|false))') AND try_cast(r."is_repeat_complainer" AS BOOLEAN) IS NOT NULL THEN 'is_repeat_complainer:F' END
    ], x -> x IS NOT NULL) AS _dq_issues
from {{ source('bronze_raw', 'complaints') }} r
